static void
requiredness_set_property (GObject *object,
                           guint property_id,
                           const GValue *value,
                           GParamSpec *pspec)
{
  Requiredness *self = REQUIREDNESS (object);

  switch (property_id)
  {
    case PROP_REQUIREDNESS_REQ_FIELD:
      self->req_field = g_value_get_int (value);
      break;

    case PROP_REQUIREDNESS_OPT_FIELD:
      self->opt_field = g_value_get_int (value);
      self->__isset_opt_field = TRUE;
      break;

    case PROP_REQUIREDNESS_DEFAULT_FIELD:
      self->default_field = g_value_get_int (value);
      self->__isset_default_field = TRUE;
      break;

    case PROP_REQUIREDNESS_OPT_WITH_DEFAULT:
      if (self->opt_with_default != NULL)
        g_free (self->opt_with_default);
      self->opt_with_default = g_value_dup_string (value);
      self->__isset_opt_with_default = TRUE;
      break;

    case PROP_REQUIREDNESS_REQ_WITH_DEFAULT:
      self->req_with_default = g_value_get_boolean (value);
      break;

    default:
      G_OBJECT_WARN_INVALID_PROPERTY_ID (object, property_id, pspec);
      break;
  }
}

static void
requiredness_get_property (GObject *object,
                           guint property_id,
                           GValue *value,
                           GParamSpec *pspec)
{
  Requiredness *self = REQUIREDNESS (object);

  switch (property_id)
  {
    case PROP_REQUIREDNESS_REQ_FIELD:
      g_value_set_int (value, self->req_field);
      break;

    case PROP_REQUIREDNESS_OPT_FIELD:
      g_value_set_int (value, self->opt_field);
      break;

    case PROP_REQUIREDNESS_DEFAULT_FIELD:
      g_value_set_int (value, self->default_field);
      break;

    case PROP_REQUIREDNESS_OPT_WITH_DEFAULT:
      g_value_set_string (value, self->opt_with_default);
      break;

    case PROP_REQUIREDNESS_REQ_WITH_DEFAULT:
      g_value_set_boolean (value, self->req_with_default);
      break;

    default:
      G_OBJECT_WARN_INVALID_PROPERTY_ID (object, property_id, pspec);
      break;
  }
}

