static void
containers_set_property (GObject *object,
                         guint property_id,
                         const GValue *value,
                         GParamSpec *pspec)
{
  Containers *self = CONTAINERS (object);

  switch (property_id)
  {
    case PROP_CONTAINERS_INT_LIST:
      if (self->int_list != NULL)
        g_array_unref (self->int_list);
      self->int_list = g_value_dup_boxed (value);
      self->__isset_int_list = TRUE;
      break;

    case PROP_CONTAINERS_STRING_SET:
      if (self->string_set != NULL)
        g_hash_table_unref (self->string_set);
      self->string_set = g_value_dup_boxed (value);
      self->__isset_string_set = TRUE;
      break;

    case PROP_CONTAINERS_INT_STRING_MAP:
      if (self->int_string_map != NULL)
        g_hash_table_unref (self->int_string_map);
      self->int_string_map = g_value_dup_boxed (value);
      self->__isset_int_string_map = TRUE;
      break;

    case PROP_CONTAINERS_STRUCT_LIST:
      if (self->struct_list != NULL)
        g_ptr_array_unref (self->struct_list);
      self->struct_list = g_value_dup_boxed (value);
      self->__isset_struct_list = TRUE;
      break;

    case PROP_CONTAINERS_NESTED_MAP:
      if (self->nested_map != NULL)
        g_hash_table_unref (self->nested_map);
      self->nested_map = g_value_dup_boxed (value);
      self->__isset_nested_map = TRUE;
      break;

    case PROP_CONTAINERS_TYPEDEF_SET:
      if (self->typedef_set != NULL)
        g_hash_table_unref (self->typedef_set);
      self->typedef_set = g_value_dup_boxed (value);
      self->__isset_typedef_set = TRUE;
      break;

    default:
      G_OBJECT_WARN_INVALID_PROPERTY_ID (object, property_id, pspec);
      break;
  }
}

static void
containers_get_property (GObject *object,
                         guint property_id,
                         GValue *value,
                         GParamSpec *pspec)
{
  Containers *self = CONTAINERS (object);

  switch (property_id)
  {
    case PROP_CONTAINERS_INT_LIST:
      g_value_set_boxed (value, self->int_list);
      break;

    case PROP_CONTAINERS_STRING_SET:
      g_value_set_boxed (value, self->string_set);
      break;

    case PROP_CONTAINERS_INT_STRING_MAP:
      g_value_set_boxed (value, self->int_string_map);
      break;

    case PROP_CONTAINERS_STRUCT_LIST:
      g_value_set_boxed (value, self->struct_list);
      break;

    case PROP_CONTAINERS_NESTED_MAP:
      g_value_set_boxed (value, self->nested_map);
      break;

    case PROP_CONTAINERS_TYPEDEF_SET:
      g_value_set_boxed (value, self->typedef_set);
      break;

    default:
      G_OBJECT_WARN_INVALID_PROPERTY_ID (object, property_id, pspec);
      break;
  }
}

static void 
containers_instance_init (Containers * object)
{
  /* satisfy -Wall */
  THRIFT_UNUSED_VAR (object);
  object->int_list = g_array_new (0, 1, sizeof (gint32));
  object->__isset_int_list = FALSE;
  object->string_set = g_hash_table_new_full (g_str_hash, g_str_equal, g_free, NULL);
  object->__isset_string_set = FALSE;
  object->int_string_map = g_hash_table_new_full (g_int_hash, g_int_equal, g_free, g_free);
  object->__isset_int_string_map = FALSE;
  object->struct_list = g_ptr_array_new_with_free_func (g_object_unref);
  object->__isset_struct_list = FALSE;
  object->nested_map = g_hash_table_new_full (g_str_hash, g_str_equal, g_free, (GDestroyNotify) g_array_unref);
  object->__isset_nested_map = FALSE;
  object->typedef_set = g_hash_table_new_full (g_int64_hash, g_int64_equal, g_free, NULL);
  object->__isset_typedef_set = FALSE;
}

static void 
containers_finalize (GObject *object)
{
  Containers *tobject = CONTAINERS (object);

  /* satisfy -Wall in case we don't use tobject */
  THRIFT_UNUSED_VAR (tobject);
  if (tobject->int_list != NULL)
  {
    g_array_unref (tobject->int_list);
    tobject->int_list = NULL;
  }
  if (tobject->string_set != NULL)
  {
    g_hash_table_destroy (tobject->string_set);
    tobject->string_set = NULL;
  }
  if (tobject->int_string_map != NULL)
  {
    g_hash_table_destroy (tobject->int_string_map);
    tobject->int_string_map = NULL;
  }
  if (tobject->struct_list != NULL)
  {
    g_ptr_array_unref (tobject->struct_list);
    tobject->struct_list = NULL;
  }
  if (tobject->nested_map != NULL)
  {
    g_hash_table_destroy (tobject->nested_map);
    tobject->nested_map = NULL;
  }
  if (tobject->typedef_set != NULL)
  {
    g_hash_table_destroy (tobject->typedef_set);
    tobject->typedef_set = NULL;
  }
}

static void
containers_class_init (ContainersClass * cls)
{
  GObjectClass *gobject_class = G_OBJECT_CLASS (cls);
  ThriftStructClass *struct_class = THRIFT_STRUCT_CLASS (cls);

  struct_class->read = containers_read;
  struct_class->write = containers_write;

  gobject_class->finalize = containers_finalize;
  gobject_class->get_property = containers_get_property;
  gobject_class->set_property = containers_set_property;

  g_object_class_install_property
    (gobject_class,
     PROP_CONTAINERS_INT_LIST,
     g_param_spec_boxed ("int_list",
                         NULL,
                         NULL,
                         G_TYPE_ARRAY,
                         G_PARAM_READWRITE));

  g_object_class_install_property
    (gobject_class,
     PROP_CONTAINERS_STRING_SET,
     g_param_spec_boxed ("string_set",
                         NULL,
                         NULL,
                         G_TYPE_HASH_TABLE,
                         G_PARAM_READWRITE));

  g_object_class_install_property
    (gobject_class,
     PROP_CONTAINERS_INT_STRING_MAP,
     g_param_spec_boxed ("int_string_map",
                         NULL,
                         NULL,
                         G_TYPE_HASH_TABLE,
                         G_PARAM_READWRITE));

  g_object_class_install_property
    (gobject_class,
     PROP_CONTAINERS_STRUCT_LIST,
     g_param_spec_boxed ("struct_list",
                         NULL,
                         NULL,
                         G_TYPE_PTR_ARRAY,
                         G_PARAM_READWRITE));

  g_object_class_install_property
    (gobject_class,
     PROP_CONTAINERS_NESTED_MAP,
     g_param_spec_boxed ("nested_map",
                         NULL,
                         NULL,
                         G_TYPE_HASH_TABLE,
                         G_PARAM_READWRITE));

  g_object_class_install_property
    (gobject_class,
     PROP_CONTAINERS_TYPEDEF_SET,
     g_param_spec_boxed ("typedef_set",
                         NULL,
                         NULL,
                         G_TYPE_HASH_TABLE,
                         G_PARAM_READWRITE));
}

GType
containers_get_type (void)
{
  static GType type = 0;

  if (type == 0) 
  {
    static const GTypeInfo type_info = 
    {
      sizeof (ContainersClass),
      NULL, /* base_init */
      NULL, /* base_finalize */
      (GClassInitFunc) containers_class_init,
      NULL, /* class_finalize */
      NULL, /* class_data */
      sizeof (Containers),
      0, /* n_preallocs */
      (GInstanceInitFunc) containers_instance_init,
      NULL, /* value_table */
    };

    type = g_type_register_static (THRIFT_TYPE_STRUCT, 
                                   "ContainersType",
                                   &type_info, 0);
  }

  return type;
}

