/* reads a fuzz_test object */
static gint32
fuzz_test_read (ThriftStruct *object, ThriftProtocol *protocol, GError **error)
{
  gint32 ret;
  gint32 xfer = 0;
  gchar *name = NULL;
  ThriftType ftype;
  gint16 fid;
  guint32 len = 0;
  gpointer data = NULL;
  FuzzTest * this_object = FUZZ_TEST(object);
  gboolean isset_basic = FALSE;
  gboolean isset_required_test = FALSE;
  gboolean isset_containers = FALSE;
  gboolean isset_union_field = FALSE;
  gboolean isset_enum_field = FALSE;

  /* satisfy -Wall in case these aren't used */
  THRIFT_UNUSED_VAR (len);
  THRIFT_UNUSED_VAR (data);
  THRIFT_UNUSED_VAR (this_object);

  /* read the struct begin marker */
  if ((ret = thrift_protocol_read_struct_begin (protocol, &name, error)) < 0)
  {
    if (name) g_free (name);
    return -1;
  }
  xfer += ret;
  if (name) g_free (name);
  name = NULL;

  /* read the struct fields */
  while (1)
  {
    /* read the beginning of a field */
    if ((ret = thrift_protocol_read_field_begin (protocol, &name, &ftype, &fid, error)) < 0)
    {
      if (name) g_free (name);
      return -1;
    }
    xfer += ret;
    if (name) g_free (name);
    name = NULL;

    /* break if we get a STOP field */
    if (ftype == T_STOP)
    {
      break;
    }

    switch (fid)
    {
      case 1:
        if (ftype == T_STRUCT)
        {
          if ((ret = thrift_struct_read (THRIFT_STRUCT (this_object->basic), protocol, error)) < 0)
          {
            return -1;
          }
          xfer += ret;
          isset_basic = TRUE;
        } else {
          if ((ret = thrift_protocol_skip (protocol, ftype, error)) < 0)
            return -1;
          xfer += ret;
        }
        break;
      case 2:
        if (ftype == T_STRUCT)
        {
          if ((ret = thrift_struct_read (THRIFT_STRUCT (this_object->required_test), protocol, error)) < 0)
          {
            return -1;
          }
          xfer += ret;
          isset_required_test = TRUE;
        } else {
          if ((ret = thrift_protocol_skip (protocol, ftype, error)) < 0)
            return -1;
          xfer += ret;
        }
        break;
      case 3:
        if (ftype == T_STRUCT)
        {
          if ((ret = thrift_struct_read (THRIFT_STRUCT (this_object->containers), protocol, error)) < 0)
          {
            return -1;
          }
          xfer += ret;
          isset_containers = TRUE;
        } else {
          if ((ret = thrift_protocol_skip (protocol, ftype, error)) < 0)
            return -1;
          xfer += ret;
        }
        break;
      case 4:
        if (ftype == T_STRUCT)
        {
          if ((ret = thrift_struct_read (THRIFT_STRUCT (this_object->union_field), protocol, error)) < 0)
          {
            return -1;
          }
          xfer += ret;
          isset_union_field = TRUE;
        } else {
          if ((ret = thrift_protocol_skip (protocol, ftype, error)) < 0)
            return -1;
          xfer += ret;
        }
        break;
      case 6:
        if (ftype == T_STRUCT)
        {
          if ((ret = thrift_struct_read (THRIFT_STRUCT (this_object->empty), protocol, error)) < 0)
          {
            return -1;
          }
          xfer += ret;
          this_object->__isset_empty = TRUE;
        } else {
          if ((ret = thrift_protocol_skip (protocol, ftype, error)) < 0)
            return -1;
          xfer += ret;
        }
        break;
      case 7:
        if (ftype == T_STRUCT)
        {
          if ((ret = thrift_struct_read (THRIFT_STRUCT (this_object->field_ids), protocol, error)) < 0)
          {
            return -1;
          }
          xfer += ret;
          this_object->__isset_field_ids = TRUE;
        } else {
          if ((ret = thrift_protocol_skip (protocol, ftype, error)) < 0)
            return -1;
          xfer += ret;
        }
        break;
      case 8:
        if (ftype == T_I32)
        {
          gint32 ecast16;
          if ((ret = thrift_protocol_read_i32 (protocol, &ecast16, error)) < 0)
            return -1;
          xfer += ret;
          this_object->enum_field = (TestEnum)ecast16;
          isset_enum_field = TRUE;
        } else {
          if ((ret = thrift_protocol_skip (protocol, ftype, error)) < 0)
            return -1;
          xfer += ret;
        }
        break;
      case 9:
        if (ftype == T_MAP)
        {
          {
            guint32 size;
            guint32 i;
            ThriftType key_type;
            ThriftType value_type;

            /* read the map begin marker */
            if ((ret = thrift_protocol_read_map_begin (protocol, &key_type, &value_type, &size, error)) < 0)
              return -1;
            xfer += ret;

            /* iterate through each of the map's fields */
            for (i = 0; i < size; i++)
            {
              TestEnum key17;
              gchar * val18 = NULL;
              gint32 ecast19;
              if ((ret = thrift_protocol_read_i32 (protocol, &ecast19, error)) < 0)
                return -1;
              xfer += ret;
              key17 = (TestEnum)ecast19;
              if (val18 != NULL)
              {
                g_free(val18);
                val18 = NULL;
              }

              if ((ret = thrift_protocol_read_string (protocol, &val18, error)) < 0)
                return -1;
              xfer += ret;
              if (this_object->enum_map && key17)
                g_hash_table_insert ((GHashTable *)this_object->enum_map, (gpointer) key17, (gpointer) val18);
            }

            /* read the map end marker */
            if ((ret = thrift_protocol_read_map_end (protocol, error)) < 0)
              return -1;
            xfer += ret;
          }
          this_object->__isset_enum_map = TRUE;
        } else {
          if ((ret = thrift_protocol_skip (protocol, ftype, error)) < 0)
            return -1;
          xfer += ret;
        }
        break;
      case 10:
        if (ftype == T_I64)
        {
          if ((ret = thrift_protocol_read_i64 (protocol, &this_object->user_id, error)) < 0)
            return -1;
          xfer += ret;
          this_object->__isset_user_id = TRUE;
        } else {
          if ((ret = thrift_protocol_skip (protocol, ftype, error)) < 0)
            return -1;
          xfer += ret;
        }
        break;
      case 11:
        if (ftype == T_STRING)
        {
          if (this_object->data != NULL)
          {
            g_byte_array_free(this_object->data, TRUE);
            this_object->data = NULL;
          }

          if ((ret = thrift_protocol_read_binary (protocol, &data, &len, error)) < 0)
            return -1;
          xfer += ret;
          this_object->data = g_byte_array_new();
          g_byte_array_append (this_object->data, (guint8 *) data, (guint) len);
          g_free (data);
          this_object->__isset_data = TRUE;
        } else {
          if ((ret = thrift_protocol_skip (protocol, ftype, error)) < 0)
            return -1;
          xfer += ret;
        }
        break;
      default:
        if ((ret = thrift_protocol_skip (protocol, ftype, error)) < 0)
          return -1;
        xfer += ret;
        break;
    }
    if ((ret = thrift_protocol_read_field_end (protocol, error)) < 0)
      return -1;
    xfer += ret;
  }

  if ((ret = thrift_protocol_read_struct_end (protocol, error)) < 0)
    return -1;
  xfer += ret;

  if (!isset_basic)
  {
    g_set_error (error, THRIFT_PROTOCOL_ERROR,
                 THRIFT_PROTOCOL_ERROR_INVALID_DATA,
                 "missing field");
    return -1;
  }

  if (!isset_required_test)
  {
    g_set_error (error, THRIFT_PROTOCOL_ERROR,
                 THRIFT_PROTOCOL_ERROR_INVALID_DATA,
                 "missing field");
    return -1;
  }

  if (!isset_containers)
  {
    g_set_error (error, THRIFT_PROTOCOL_ERROR,
                 THRIFT_PROTOCOL_ERROR_INVALID_DATA,
                 "missing field");
    return -1;
  }

  if (!isset_union_field)
  {
    g_set_error (error, THRIFT_PROTOCOL_ERROR,
                 THRIFT_PROTOCOL_ERROR_INVALID_DATA,
                 "missing field");
    return -1;
  }

  if (!isset_enum_field)
  {
    g_set_error (error, THRIFT_PROTOCOL_ERROR,
                 THRIFT_PROTOCOL_ERROR_INVALID_DATA,
                 "missing field");
    return -1;
  }

  return xfer;
}

static gint32
fuzz_test_write (ThriftStruct *object, ThriftProtocol *protocol, GError **error)
{
  gint32 ret;
  gint32 xfer = 0;

  FuzzTest * this_object = FUZZ_TEST(object);
  THRIFT_UNUSED_VAR (this_object);
  if ((ret = thrift_protocol_write_struct_begin (protocol, "FuzzTest", error)) < 0)
    return -1;
  xfer += ret;
  if ((ret = thrift_protocol_write_field_begin (protocol, "basic", T_STRUCT, 1, error)) < 0)
    return -1;
  xfer += ret;
  if ((ret = thrift_struct_write (THRIFT_STRUCT (this_object->basic), protocol, error)) < 0)
    return -1;
  xfer += ret;

  if ((ret = thrift_protocol_write_field_end (protocol, error)) < 0)
    return -1;
  xfer += ret;
  if ((ret = thrift_protocol_write_field_begin (protocol, "required_test", T_STRUCT, 2, error)) < 0)
    return -1;
  xfer += ret;
  if ((ret = thrift_struct_write (THRIFT_STRUCT (this_object->required_test), protocol, error)) < 0)
    return -1;
  xfer += ret;

  if ((ret = thrift_protocol_write_field_end (protocol, error)) < 0)
    return -1;
  xfer += ret;
  if ((ret = thrift_protocol_write_field_begin (protocol, "containers", T_STRUCT, 3, error)) < 0)
    return -1;
  xfer += ret;
  if ((ret = thrift_struct_write (THRIFT_STRUCT (this_object->containers), protocol, error)) < 0)
    return -1;
  xfer += ret;

  if ((ret = thrift_protocol_write_field_end (protocol, error)) < 0)
    return -1;
  xfer += ret;
  if ((ret = thrift_protocol_write_field_begin (protocol, "union_field", T_STRUCT, 4, error)) < 0)
    return -1;
  xfer += ret;
  if ((ret = thrift_struct_write (THRIFT_STRUCT (this_object->union_field), protocol, error)) < 0)
    return -1;
  xfer += ret;

  if ((ret = thrift_protocol_write_field_end (protocol, error)) < 0)
    return -1;
  xfer += ret;
  if (this_object->__isset_empty == TRUE) {
    if ((ret = thrift_protocol_write_field_begin (protocol, "empty", T_STRUCT, 6, error)) < 0)
      return -1;
    xfer += ret;
    if ((ret = thrift_struct_write (THRIFT_STRUCT (this_object->empty), protocol, error)) < 0)
      return -1;
    xfer += ret;

    if ((ret = thrift_protocol_write_field_end (protocol, error)) < 0)
      return -1;
    xfer += ret;
  }
  if (this_object->__isset_field_ids == TRUE) {
    if ((ret = thrift_protocol_write_field_begin (protocol, "field_ids", T_STRUCT, 7, error)) < 0)
      return -1;
    xfer += ret;
    if ((ret = thrift_struct_write (THRIFT_STRUCT (this_object->field_ids), protocol, error)) < 0)
      return -1;
    xfer += ret;

    if ((ret = thrift_protocol_write_field_end (protocol, error)) < 0)
      return -1;
    xfer += ret;
  }
  if ((ret = thrift_protocol_write_field_begin (protocol, "enum_field", T_I32, 8, error)) < 0)
    return -1;
  xfer += ret;
  if ((ret = thrift_protocol_write_i32 (protocol, (gint32) this_object->enum_field, error)) < 0)
    return -1;
  xfer += ret;

  if ((ret = thrift_protocol_write_field_end (protocol, error)) < 0)
    return -1;
  xfer += ret;
  if (this_object->__isset_enum_map == TRUE) {
    if ((ret = thrift_protocol_write_field_begin (protocol, "enum_map", T_MAP, 9, error)) < 0)
      return -1;
    xfer += ret;
    {
      TestEnum key20;
      gchar * val21 = NULL;
      GList *key_list = NULL, *iter = NULL;
      TestEnum* keys;
      int i = 0, key_count;

      if ((ret = thrift_protocol_write_map_begin (protocol, T_I32, T_STRING, this_object->enum_map ? (gint32) g_hash_table_size ((GHashTable *) this_object->enum_map) : 0, error)) < 0)
        return -1;
      xfer += ret;
      if (this_object->enum_map)
        g_hash_table_foreach ((GHashTable *) this_object->enum_map, thrift_hash_table_get_keys, &key_list);
      key_count = g_list_length (key_list);
      keys = g_newa (TestEnum, key_count);
      for (iter = g_list_first (key_list); iter; iter = iter->next)
        keys[i++] = (TestEnum) iter->data;
      g_list_free (key_list);

      for (i = 0; i < key_count; ++i)
      {
        key20 = keys[i];
        val21 = (gchar *) g_hash_table_lookup (((GHashTable *) this_object->enum_map), (gpointer) key20);

        if ((ret = thrift_protocol_write_i32 (protocol, (gint32)  key20, error)) < 0)
          return -1;
        xfer += ret;

        if ((ret = thrift_protocol_write_string (protocol,  val21, error)) < 0)
          return -1;
        xfer += ret;

      }
      if ((ret = thrift_protocol_write_map_end (protocol, error)) < 0)
        return -1;
      xfer += ret;
    }
    if ((ret = thrift_protocol_write_field_end (protocol, error)) < 0)
      return -1;
    xfer += ret;
  }
  if ((ret = thrift_protocol_write_field_begin (protocol, "user_id", T_I64, 10, error)) < 0)
    return -1;
  xfer += ret;
  if ((ret = thrift_protocol_write_i64 (protocol, this_object->user_id, error)) < 0)
    return -1;
  xfer += ret;

  if ((ret = thrift_protocol_write_field_end (protocol, error)) < 0)
    return -1;
  xfer += ret;
  if ((ret = thrift_protocol_write_field_begin (protocol, "data", T_STRING, 11, error)) < 0)
    return -1;
  xfer += ret;
  if ((ret = thrift_protocol_write_binary (protocol, this_object->data ? ((GByteArray *) this_object->data)->data : NULL, this_object->data ? ((GByteArray *) this_object->data)->len : 0, error)) < 0)
    return -1;
  xfer += ret;

  if ((ret = thrift_protocol_write_field_end (protocol, error)) < 0)
    return -1;
  xfer += ret;
  if ((ret = thrift_protocol_write_field_stop (protocol, error)) < 0)
    return -1;
  xfer += ret;
  if ((ret = thrift_protocol_write_struct_end (protocol, error)) < 0)
    return -1;
  xfer += ret;

  return xfer;
}

static void
fuzz_test_set_property (GObject *object,
                        guint property_id,
                        const GValue *value,
                        GParamSpec *pspec)
{
  FuzzTest *self = FUZZ_TEST (object);

  switch (property_id)
  {
    case PROP_FUZZ_TEST_BASIC:
      if (self->basic != NULL)
        g_object_unref (self->basic);
      self->basic = g_value_dup_object (value);
      break;

    case PROP_FUZZ_TEST_REQUIRED_TEST:
      if (self->required_test != NULL)
        g_object_unref (self->required_test);
      self->required_test = g_value_dup_object (value);
      break;

    case PROP_FUZZ_TEST_CONTAINERS:
      if (self->containers != NULL)
        g_object_unref (self->containers);
      self->containers = g_value_dup_object (value);
      break;

    case PROP_FUZZ_TEST_UNION_FIELD:
      if (self->union_field != NULL)
        g_object_unref (self->union_field);
      self->union_field = g_value_dup_object (value);
      break;

    case PROP_FUZZ_TEST_EMPTY:
      if (self->empty != NULL)
        g_object_unref (self->empty);
      self->empty = g_value_dup_object (value);
      self->__isset_empty = TRUE;
      break;

    case PROP_FUZZ_TEST_FIELD_IDS:
      if (self->field_ids != NULL)
        g_object_unref (self->field_ids);
      self->field_ids = g_value_dup_object (value);
      self->__isset_field_ids = TRUE;
      break;

    case PROP_FUZZ_TEST_ENUM_FIELD:
      self->enum_field = g_value_get_int (value);
      break;

    case PROP_FUZZ_TEST_ENUM_MAP:
      if (self->enum_map != NULL)
        g_hash_table_unref (self->enum_map);
      self->enum_map = g_value_dup_boxed (value);
      self->__isset_enum_map = TRUE;
      break;

    case PROP_FUZZ_TEST_USER_ID:
      self->user_id = g_value_get_int64 (value);
      self->__isset_user_id = TRUE;
      break;

    case PROP_FUZZ_TEST_DATA:
      if (self->data != NULL)
        g_byte_array_unref (self->data);
      self->data = g_value_dup_boxed (value);
      self->__isset_data = TRUE;
      break;

    default:
      G_OBJECT_WARN_INVALID_PROPERTY_ID (object, property_id, pspec);
      break;
  }
}

static void
fuzz_test_get_property (GObject *object,
                        guint property_id,
                        GValue *value,
                        GParamSpec *pspec)
{
  FuzzTest *self = FUZZ_TEST (object);

  switch (property_id)
  {
    case PROP_FUZZ_TEST_BASIC:
      g_value_set_object (value, self->basic);
      break;

    case PROP_FUZZ_TEST_REQUIRED_TEST:
      g_value_set_object (value, self->required_test);
      break;

    case PROP_FUZZ_TEST_CONTAINERS:
      g_value_set_object (value, self->containers);
      break;

    case PROP_FUZZ_TEST_UNION_FIELD:
      g_value_set_object (value, self->union_field);
      break;

    case PROP_FUZZ_TEST_EMPTY:
      g_value_set_object (value, self->empty);
      break;

    case PROP_FUZZ_TEST_FIELD_IDS:
      g_value_set_object (value, self->field_ids);
      break;

    case PROP_FUZZ_TEST_ENUM_FIELD:
      g_value_set_int (value, self->enum_field);
      break;

    case PROP_FUZZ_TEST_ENUM_MAP:
      g_value_set_boxed (value, self->enum_map);
      break;

    case PROP_FUZZ_TEST_USER_ID:
      g_value_set_int64 (value, self->user_id);
      break;

    case PROP_FUZZ_TEST_DATA:
      g_value_set_boxed (value, self->data);
      break;

    default:
      G_OBJECT_WARN_INVALID_PROPERTY_ID (object, property_id, pspec);
      break;
  }
}

static void 
fuzz_test_instance_init (FuzzTest * object)
{
  /* satisfy -Wall */
  THRIFT_UNUSED_VAR (object);
  object->basic = g_object_new (TYPE_BASIC_TYPES, NULL);
  object->required_test = g_object_new (TYPE_REQUIREDNESS, NULL);
  object->containers = g_object_new (TYPE_CONTAINERS, NULL);
  object->union_field = g_object_new (TYPE_TEST_UNION, NULL);
  object->empty = g_object_new (TYPE_EMPTY_STRUCT, NULL);
  object->__isset_empty = FALSE;
  object->field_ids = g_object_new (TYPE_FIELD_I_D_TEST, NULL);
  object->__isset_field_ids = FALSE;
  object->enum_map = g_hash_table_new_full (g_direct_hash, g_direct_equal, NULL, g_free);
  object->__isset_enum_map = FALSE;
  object->user_id = 0;
  object->__isset_user_id = FALSE;
  object->data = NULL;
  object->__isset_data = FALSE;
}

static void 
fuzz_test_finalize (GObject *object)
{
  FuzzTest *tobject = FUZZ_TEST (object);

  /* satisfy -Wall in case we don't use tobject */
  THRIFT_UNUSED_VAR (tobject);
  if (tobject->basic != NULL)
  {
    g_object_unref(tobject->basic);
    tobject->basic = NULL;
  }
  if (tobject->required_test != NULL)
  {
    g_object_unref(tobject->required_test);
    tobject->required_test = NULL;
  }
  if (tobject->containers != NULL)
  {
    g_object_unref(tobject->containers);
    tobject->containers = NULL;
  }
  if (tobject->union_field != NULL)
  {
    g_object_unref(tobject->union_field);
    tobject->union_field = NULL;
  }
  if (tobject->empty != NULL)
  {
    g_object_unref(tobject->empty);
    tobject->empty = NULL;
  }
  if (tobject->field_ids != NULL)
  {
    g_object_unref(tobject->field_ids);
    tobject->field_ids = NULL;
  }
  if (tobject->enum_map != NULL)
  {
    g_hash_table_destroy (tobject->enum_map);
    tobject->enum_map = NULL;
  }
  if (tobject->data != NULL)
  {
    thrift_string_free(tobject->data);
    tobject->data = NULL;
  }
}

static void
fuzz_test_class_init (FuzzTestClass * cls)
{
  GObjectClass *gobject_class = G_OBJECT_CLASS (cls);
  ThriftStructClass *struct_class = THRIFT_STRUCT_CLASS (cls);

  struct_class->read = fuzz_test_read;
  struct_class->write = fuzz_test_write;

  gobject_class->finalize = fuzz_test_finalize;
  gobject_class->get_property = fuzz_test_get_property;
  gobject_class->set_property = fuzz_test_set_property;

  g_object_class_install_property
    (gobject_class,
     PROP_FUZZ_TEST_BASIC,
     g_param_spec_object ("basic",
                         NULL,
                         NULL,
                         TYPE_BASIC_TYPES,
                         G_PARAM_READWRITE));

  g_object_class_install_property
    (gobject_class,
     PROP_FUZZ_TEST_REQUIRED_TEST,
     g_param_spec_object ("required_test",
                         NULL,
                         NULL,
                         TYPE_REQUIREDNESS,
                         G_PARAM_READWRITE));

  g_object_class_install_property
    (gobject_class,
     PROP_FUZZ_TEST_CONTAINERS,
     g_param_spec_object ("containers",
                         NULL,
                         NULL,
                         TYPE_CONTAINERS,
                         G_PARAM_READWRITE));

  g_object_class_install_property
    (gobject_class,
     PROP_FUZZ_TEST_UNION_FIELD,
     g_param_spec_object ("union_field",
                         NULL,
                         NULL,
                         TYPE_TEST_UNION,
                         G_PARAM_READWRITE));

  g_object_class_install_property
    (gobject_class,
     PROP_FUZZ_TEST_EMPTY,
     g_param_spec_object ("empty",
                         NULL,
                         NULL,
                         TYPE_EMPTY_STRUCT,
                         G_PARAM_READWRITE));

  g_object_class_install_property
    (gobject_class,
     PROP_FUZZ_TEST_FIELD_IDS,
     g_param_spec_object ("field_ids",
                         NULL,
                         NULL,
                         TYPE_FIELD_I_D_TEST,
                         G_PARAM_READWRITE));

  g_object_class_install_property
    (gobject_class,
     PROP_FUZZ_TEST_ENUM_FIELD,
     g_param_spec_int ("enum_field",
                       NULL,
                       NULL,
                       -1,
                       32767,
                       -1,
                       G_PARAM_READWRITE));

  g_object_class_install_property
    (gobject_class,
     PROP_FUZZ_TEST_ENUM_MAP,
     g_param_spec_boxed ("enum_map",
                         NULL,
                         NULL,
                         G_TYPE_HASH_TABLE,
                         G_PARAM_READWRITE));

  g_object_class_install_property
    (gobject_class,
     PROP_FUZZ_TEST_USER_ID,
     g_param_spec_int64 ("user_id",
                         NULL,
                         NULL,
                         G_MININT64,
                         G_MAXINT64,
                         0,
                         G_PARAM_READWRITE));

  g_object_class_install_property
    (gobject_class,
     PROP_FUZZ_TEST_DATA,
     g_param_spec_boxed ("data",
                         NULL,
                         NULL,
                         G_TYPE_BYTE_ARRAY,
                         G_PARAM_READWRITE));
}

GType
fuzz_test_get_type (void)
{
  static GType type = 0;

  if (type == 0) 
  {
    static const GTypeInfo type_info = 
    {
      sizeof (FuzzTestClass),
      NULL, /* base_init */
      NULL, /* base_finalize */
      (GClassInitFunc) fuzz_test_class_init,
      NULL, /* class_finalize */
      NULL, /* class_data */
      sizeof (FuzzTest),
      0, /* n_preallocs */
      (GInstanceInitFunc) fuzz_test_instance_init,
      NULL, /* value_table */
    };

    type = g_type_register_static (THRIFT_TYPE_STRUCT, 
                                   "FuzzTestType",
                                   &type_info, 0);
  }

  return type;
}

